import math
import re

_UNITS = {
    "s": 1, "sec": 1, "secs": 1, "second": 1, "seconds": 1,
    "m": 60, "min": 60, "mins": 60, "minute": 60, "minutes": 60,
    "h": 3600, "hr": 3600, "hrs": 3600, "hour": 3600, "hours": 3600,
    "d": 86400, "day": 86400, "days": 86400,
    "w": 604800, "wk": 604800, "wks": 604800, "week": 604800, "weeks": 604800,
}

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_COMPONENT_RE = re.compile(r"\s*(" + _NUM + r")\s*([A-Za-z]+)\s*")
_ISO_RE = re.compile(
    r"P(?:(" + _NUM + r")W)?(?:(" + _NUM + r")D)?"
    r"(?:T(?:(" + _NUM + r")H)?(?:(" + _NUM + r")M)?(?:(" + _NUM + r")S)?)?",
    re.IGNORECASE,
)
_CLOCK_RE = re.compile(r"(\d+)(?::(\d+))?(?::(\d+(?:\.\d*)?|\.\d+))?")


def _round(value):
    return int(math.floor(value + 0.5))


def _from_fields(fields):
    """Sum (number_str, multiplier) pairs; None entries are skipped."""
    total = 0.0
    any_field = False
    for num, mult in fields:
        if num is None:
            continue
        any_field = True
        total += float(num) * mult
    if not any_field:
        raise ValueError("empty duration")
    return _round(total)


def _parse_iso(text):
    m = _ISO_RE.fullmatch(text)
    if not m:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    weeks, days, hours, minutes, seconds = m.groups()
    if text.upper().endswith("T"):
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    return _from_fields([
        (weeks, _UNITS["w"]),
        (days, _UNITS["d"]),
        (hours, _UNITS["h"]),
        (minutes, _UNITS["m"]),
        (seconds, _UNITS["s"]),
    ])


def _parse_clock(text):
    m = _CLOCK_RE.fullmatch(text)
    if not m:
        raise ValueError(f"invalid clock duration: {text!r}")
    a, b, c = m.groups()
    if c is None and b is None:
        raise ValueError("bare integer handled elsewhere")
    if c is None:
        # mm:ss
        fields = [(a, 60), (b, 1)]
    else:
        # hh:mm:ss
        fields = [(a, 3600), (b, 60), (c, 1)]
    for num, _ in fields:
        if num is None:
            raise ValueError(f"invalid clock duration: {text!r}")
    if c is None:
        # minutes field must be < 60 only when it is not the leading field; keep lenient
        pass
    else:
        if int(b) >= 60 and len(b) > 0:
            raise ValueError(f"invalid clock duration: {text!r}")
    if c is not None and float(c) >= 60:
        raise ValueError(f"invalid clock duration: {text!r}")
    if b is not None and c is None and float(b) >= 60:
        raise ValueError(f"invalid clock duration: {text!r}")
    return _from_fields(fields)


def _parse_components(text):
    pos = 0
    fields = []
    while pos < len(text):
        m = _COMPONENT_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ValueError(f"invalid duration: {text!r}")
        num, unit = m.group(1), m.group(2).lower()
        if unit not in _UNITS:
            raise ValueError(f"unknown unit: {unit!r}")
        fields.append((num, _UNITS[unit]))
        pos = m.end()
    if not fields:
        raise ValueError("empty duration")
    return _from_fields(fields)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")
    if s.startswith("-") or s.startswith("+"):
        raise ValueError(f"signed durations are not allowed: {text!r}")
    if s[0] in "Pp":
        return _parse_iso(s.upper())
    if re.fullmatch(r"\d+", s):
        return int(s)
    if ":" in s:
        return _parse_clock(s)
    return _parse_components(s)

